import React from "react";
import { useLocation, Route, Routes, Navigate } from "react-router-dom";
import { Container } from "reactstrap";
// Core components
import AdminNavbar from "components/Navbars/AdminNavbar.js";
import AdminFooter from "components/Footers/AdminFooter.js";
import Sidebar from "components/Sidebar/Sidebar.js";
import PrivateRoute from "./PrivateRoute"; // Import PrivateRoute

import routes from "routes.js";

const Admin = (props) => {
  const mainContent = React.useRef(null);
  const location = useLocation();

  console.log("Admin Component: Mounted");
  console.log("Current Path:", location.pathname);

  React.useEffect(() => {
    console.log("Admin Component: Scrolling to top on route change");
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    if (mainContent.current) {
      mainContent.current.scrollTop = 0;
    }
  }, [location]);

  const getRoutes = (routes) => {
    console.log("Admin Component: Mapping routes...");
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        console.log(`Admin Route Found: ${prop.path}`);
        return (
          <Route 
            path={prop.path} 
            element={<PrivateRoute element={prop.component} />} 
            key={key} 
            exact 
          />
        );
      } else {
        console.log(`Skipping Non-Admin Route: ${prop.path}`);
        return null;
      }
    });
  };

  const getBrandText = (path) => {
    for (let i = 0; i < routes.length; i++) {
      if (path.includes(routes[i].layout + routes[i].path)) {
        console.log(`Admin Navbar: Setting brand text to ${routes[i].name}`);
        return routes[i].name;
      }
    }
    return "EcoCred";
  };

  return (
    <>
      <Sidebar
        {...props}
        routes={routes}
        logo={{
          innerLink: "/admin/index",
          imgAlt: "...",
        }}
      />
      <div className="main-content" ref={mainContent}>
        <AdminNavbar
          {...props}
          brandText={getBrandText(location.pathname)}
        />
        <Routes>
          {getRoutes(routes)}
          <Route path="*" element={<Navigate to="/admin/index" replace />} />
        </Routes>
        <Container fluid>
          <AdminFooter />
        </Container>
      </div>
    </>
  );
};

export default Admin;
